export const ARK_GM_ITEM_OPTIONS: ArkGmItemOption[] = ARK_GM_ITEM_TUPLES.map(([name, category, itemId, gfiCode, blueprintPath]) => ({
  value: blueprintPath,
  label: `${name} / ${category} / ${gfiCode}`,
  name,
  category,
  itemId,
  gfiCode,
  blueprintPath
}));

export const ARK_GM_NUMERIC_ITEM_OPTIONS: ArkGmItemOption[] = ARK_GM_ITEM_OPTIONS.filter((option) => /^\d+$/.test(option.itemId)).map((option) => ({
  ...option,
  value: option.itemId,
  label: `${option.name} / ${option.category} / #${option.itemId}`
}));

type ArkGmItemSearchEntry = {
  option: ArkGmItemOption;
  text: string;
  name: string;
  category: string;
  itemId: string;
  gfiCode: string;
  blueprintPath: string;
  localizedName: string;
  localizedCategory: string;
  order: number;
};

let itemSearchIndex: ArkGmItemSearchEntry[] | undefined;
let numericItemSearchIndex: ArkGmItemSearchEntry[] | undefined;

function buildArkGmItemSearchIndex(options: readonly ArkGmItemOption[]): ArkGmItemSearchEntry[] {
  return options.map((option, order) => {
    const aliases = arkCatalogSearchAliases(option);
    const [localizedName = "", ...localizedCategory] = aliases.split(" ");
    return {
      option,
      text: normalizeArkGmItemSearchText([option.name, option.category, option.itemId, option.gfiCode, option.blueprintPath, aliases].join(" ")),
      name: normalizeArkGmItemSearchText(option.name),
      category: normalizeArkGmItemSearchText(option.category),
      itemId: normalizeArkGmItemSearchText(option.itemId),
      gfiCode: normalizeArkGmItemSearchText(option.gfiCode),
      blueprintPath: normalizeArkGmItemSearchText(option.blueprintPath),
      localizedName: normalizeArkGmItemSearchText(localizedName),
      localizedCategory: normalizeArkGmItemSearchText(localizedCategory.join(" ")),
      order
    };
  });
}

export function searchArkGmItemOptions(query: string, limit = 80): ArkGmItemOption[] {
  const normalized = normalizeArkGmItemSearchText(query);
  if (!normalized) return ARK_GM_ITEM_OPTIONS.slice(0, limit);
  itemSearchIndex ??= buildArkGmItemSearchIndex(ARK_GM_ITEM_OPTIONS);
  return searchArkGmItemIndex(itemSearchIndex, normalized, limit);
}

export function searchArkGmNumericItemOptions(query: string, limit = 80): ArkGmItemOption[] {
  const normalized = normalizeArkGmItemSearchText(query);
  if (!normalized) return ARK_GM_NUMERIC_ITEM_OPTIONS.slice(0, limit);
  numericItemSearchIndex ??= buildArkGmItemSearchIndex(ARK_GM_NUMERIC_ITEM_OPTIONS);
  return searchArkGmItemIndex(numericItemSearchIndex, normalized, limit);
}

function searchArkGmItemIndex(
  index: ArkGmItemSearchEntry[],
  query: string,
  limit: number
): ArkGmItemOption[] {
  return index
    .map((entry) => ({ entry, score: scoreArkGmItemMatch(entry, query) }))
    .filter((match) => Number.isFinite(match.score))
    .sort((left, right) => left.score - right.score || left.entry.order - right.entry.order)
    .slice(0, limit)
    .map((match) => match.entry.option);
}

function scoreArkGmItemMatch(entry: ArkGmItemSearchEntry, query: string): number {
  if (entry.name === query) return 0;
  if (entry.localizedName === query) return 0;
  if (entry.itemId === query || entry.gfiCode === query) return 1;
  if (startsWithArkGmSearchTerm(entry.name, query)) return 2;
  if (startsWithArkGmSearchTerm(entry.localizedName, query)) return 2;
  if (containsArkGmSearchTerm(entry.name, query)) return 3;
  if (containsArkGmSearchTerm(entry.localizedName, query)) return 3;
  if (startsWithArkGmSearchTerm(entry.gfiCode, query) || startsWithArkGmSearchTerm(entry.itemId, query)) return 4;
  if (entry.category === query) return 5;
  if (entry.localizedCategory === query) return 5;
  if (entry.text.includes(query)) return 10;
  return Number.POSITIVE_INFINITY;
}

function startsWithArkGmSearchTerm(value: string, query: string): boolean {
  return value === query || value.startsWith(`${query} `) || value.startsWith(`${query}-`) || value.startsWith(`${query}_`);
}

function containsArkGmSearchTerm(value: string, query: string): boolean {
  return startsWithArkGmSearchTerm(value, query)
    || value.includes(` ${query}`)
    || value.includes(`-${query}`)
    || value.includes(`_${query}`)
    || value.includes(`/${query}`);
}

function normalizeArkGmItemSearchText(value: string): string {
  return value.trim().toLowerCase().replace(/[^\p{L}\p{N}_#'/. -]+/gu, " ").replace(/\s+/g, " ");
}
